        if isinstance(c,list):
            if any(b.get('type')=='tool_result' for b in c):continue
            c=''.join(b.get('text','') for b in c if b.get('type')=='text')
        t=clean(c)
        if not t:continue
        out.append(('U',ts,t,d.get('isSidechain')))
    else:
        t='\n'.join(b['text'] for b in c if b.get('type')=='text') if isinstance(c,list) else c
        if t.strip():out.append(('A',ts,t.strip(),d.get('isSidechain')))
json.dump(out,open(S+'msgs.json','w'))
print(len(out),sum(1 for o in out if o[0]=='U'))
for i,o in enumerate(out):
    if o[0]=='U':print(i,o[1][11:19],len(o[2]),o[2][:90].replace('\n',' '))
